result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/demux.py", "content": """"FASTQ barcode demultiplexer.

Assigns reads to samples by comparing the first 6 bases of each read
against an inline barcode map (Hamming distance 0 or 1; the barcodes are
pairwise >= 4 apart so 1-mismatch assignment is unambiguous). Assigned
reads have the barcode stripped; everything else goes to undetermined.
"""

import itertools

BARCODES = {
    "ACGTAC": "sample1",
    "TGCATG": "sample2",
    "AACCGG": "sample3",
    "TTGGCC": "sample4",
}

BARCODE_LEN = 6
MAX_MISMATCH = 1


def hamming(a: str, b: str) -> int:
    if len(a) != len(b):
        raise ValueError("sequences must have equal length")
    return sum(x != y for x, y in zip(a, b))


def assign(barcode: str):
    """Return sample name for a barcode at distance <= 1, else None."""
    best_sample = None
    best_dist = BARCODE_LEN + 1
    for ref, sample in BARCODES.items():
        d = hamming(barcode, ref)
        if d < best_dist:
            best_dist = d
            best_sample = sample
        elif d == best_dist and sample != best_sample:
            # tie -> ambiguous (cannot happen with this map, but stay safe)
            return None
    if best_dist <= MAX_MISMATCH:
        return best_sample
    return None


def read_fastq(path: str):
    """Yield (header, seq, plus, qual) records from a FASTQ file."""
    with open(path) as fh:
        while True:
            header = fh.readline()
            if not header:
                break
            seq = fh.readline()
            plus = fh.readline()
            qual = fh.readline()
            if not (seq and plus and qual):
                raise ValueError(f"truncated FASTQ record near: {header!r}")
            yield header.rstrip("\n"), seq.rstrip("\n"), plus.rstrip("\n"), qual.rstrip("\n")


def write_record(fh, rec, seq=None, qual=None):
    header, s, plus, q = rec
    if seq is not None:
        assert len(seq) == len(qual), "sequence/quality length mismatch"
        s, q = seq, qual
    fh.write(f"{header}\n{s}\n{plus}\n{q}\n")


def demultiplex(in_fastq: str, out_prefix: str):
    """Demultiplex in_fastq into out_prefix.<sample>.fastq files.

    Returns a dict {sample: count} including 'undetermined'.
    """
    outs = {
        sample: open(f"{out_prefix}.{sample}.fastq", "w")
        for sample in list(BARCODES.values()) + ["undetermined"]
    }
    counts = {s: 0 for s in outs}
    try:
        for rec in read_fastq(in_fastq):
            bc = rec[1][:BARCODE_LEN]
            sample = assign(bc)
            if sample is not None:
                write_record(outs[sample], rec, seq=rec[1][BARCODE_LEN:], qual=rec[3][BARCODE_LEN:])
            else:
                write_record(outs["undetermined"], rec)
            counts[sample or "undetermined"] += 1
    finally:
        for fh in outs.values():
            fh.close()
    return counts


if __name__ == "__main__":
    import argparse

    p = argparse.ArgumentParser(description="inline-barcode FASTQ demultiplexer")
    p.add_argument("fastq")
    p.add_argument("-o", "--out-prefix", default="demux")
    args = p.parse_args()
    counts = demultiplex(args.fastq, args.out_prefix)
    for sample, n in sorted(counts.items()):
        print(f"{sample}\t{n}")
